const campaigns = $('Filter buildable campaigns').all();
const configs = $('Get campaign config').all();
const statusMap = { ENABLED: 'active', PAUSED: 'paused' };
const output = [];

campaigns.forEach((c, i) => {
  const results = (configs[i] && configs[i].json.results) || [];
  const row = results[0];
  // No row back (campaign not found) or an explicit REMOVED status both
  // mean this campaign no longer exists in Google Ads -- Google Ads never
  // hard-deletes a campaign, 'removed' is the terminal state, same
  // convention delete-campaign.json uses when the agency deletes from the
  // dashboard. Route these to get deleted from Supabase too instead of
  // silently going stale, so a delete on either side reflects on the other.
  const removed = !row || row.campaign.status === 'REMOVED';
  if (removed) {
    output.push({ json: { campaignRowId: c.json.campaignRowId, removed: true } });
    return;
  }
  output.push({
    json: {
      campaignRowId: c.json.campaignRowId,
      removed: false,
      status: statusMap[row.campaign.status] || 'paused',
      dailyBudgetUsd: Number(row.campaignBudget.amountMicros || 0) / 1000000,
    },
  });
});

return output;

const rows = $input.all().map(i => i.json);
const DIRECT_ACCESS_CUSTOMER_IDS = ['3534195221'];
const mccCustomerId = $('Get Google Ads credentials').first().json.mcc_customer_id;
const byCustomer = new Map();

for (const row of rows) {
  if (!row.google_ads_customer_id) continue;
  const customerId = String(row.google_ads_customer_id).replace(/[^0-9]/g, '');
  if (!byCustomer.has(customerId)) {
    byCustomer.set(customerId, {
      customerId,
      clientIds: new Set(),
      loginCustomerId: DIRECT_ACCESS_CUSTOMER_IDS.includes(customerId) ? '' : mccCustomerId,
      knownResources: [],
    });
  }
  const entry = byCustomer.get(customerId);
  entry.clientIds.add(row.client_id);
  if (row.google_ads_campaign_resource) {
    entry.knownResources.push(row.google_ads_campaign_resource);
  }
}

// A customer_id shared by more than one client is ambiguous — a newly
// discovered campaign for it can't be safely attributed to either one, so
// skip discovery for it entirely rather than guessing. (This happened for
// real: two test clients briefly shared one Google Ads account, and 5
// campaigns got silently misattributed as a result before this guard.)
const out = [];
for (const entry of byCustomer.values()) {
  if (entry.clientIds.size > 1) continue;
  out.push({
    json: {
      customerId: entry.customerId,
      clientId: [...entry.clientIds][0],
      loginCustomerId: entry.loginCustomerId,
      knownResources: entry.knownResources,
    },
  });
}
return out;

