function safeAll(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
}

const customers = [...safeAll('Get distinct customers'), ...safeAll('Prepare for campaign discovery'), ...safeAll('Get clients pending discovery')];
// Matches each 'Discover campaigns' response back to the customer context
// that produced it by customerId (extracted from the response's own
// campaign.resourceName, e.g. customers/123/campaigns/456) instead of by
// array index -- index-based pairing would silently break whenever more
// than one of the three sources above produces items in the same run,
// since it depends on n8n's merge order for three separate upstream
// connections matching the concatenation order here, which isn't
// guaranteed.
const byCustomerId = new Map();
for (const c of customers) {
  byCustomerId.set(String(c.json.customerId), c.json);
}

const searches = $input.all();
const statusMap = { ENABLED: 'active', PAUSED: 'paused' };
const output = [];

searches.forEach((s) => {
  const results = (s.json && s.json.results) || [];
  for (const r of results) {
    const resourceName = r.campaign.resourceName;
    if (!resourceName) continue;
    const match = /^customers\/(\d+)\//.exec(resourceName);
    const ctx = match ? byCustomerId.get(match[1]) : null;
    if (!ctx || ctx.knownResources.includes(resourceName)) continue;
    output.push({
      json: {
        clientId: ctx.clientId,
        customerId: ctx.customerId,
        campaignName: r.campaign.name,
        status: statusMap[r.campaign.status] || 'paused',
        dailyBudgetUsd: Number((r.campaignBudget && r.campaignBudget.amountMicros) || 0) / 1000000,
        campaignResource: resourceName,
        budgetResource: (r.campaignBudget && r.campaignBudget.resourceName) || null,
      },
    });
  }
});

return output;

