const rows = $('Get all campaigns').all().map(i => i.json);
const knownCustomerIdsFromCampaigns = new Set(
  rows.filter(r => r.google_ads_customer_id).map(r => String(r.google_ads_customer_id).replace(/[^0-9]/g, ''))
);

const clients = $('Get all clients').all().map(i => i.json);
const existingClientByCustomerId = new Map();
for (const c of clients) {
  const m = /^googleads-(\d+)@discovered\.local$/.exec(c.email || '');
  if (m) existingClientByCustomerId.set(m[1], c.id);
}

const mccCustomerId = $('Get Google Ads credentials').first().json.mcc_customer_id;
const results = $json.results || [];

return results
  .filter(r => !knownCustomerIdsFromCampaigns.has(String(r.customerClient.id)))
  .map(r => {
    const customerId = String(r.customerClient.id);
    return {
      json: {
        customerId,
        descriptiveName: r.customerClient.descriptiveName || ('Google Ads ' + customerId),
        loginCustomerId: mccCustomerId,
        existingClientId: existingClientByCustomerId.get(customerId) || null,
      },
    };
  });

const source = $('Filter unknown accounts').item.json;
const clientId = source.existingClientId || $json.id;
return [{
  json: {
    customerId: source.customerId,
    clientId,
    loginCustomerId: source.loginCustomerId,
    knownResources: [],
  },
}];

const clients = $input.all().map(i => i.json);
const campaignRows = $('Get all campaigns').all().map(i => i.json).filter(r => r && r.client_id);
const clientIdsWithCampaigns = new Set(campaignRows.map(r => r.client_id));

const DIRECT_ACCESS_CUSTOMER_IDS = ['3534195221'];
const mccCustomerId = $('Get Google Ads credentials').first().json.mcc_customer_id;

const pending = clients.filter(c => c.google_ads_customer_id && !clientIdsWithCampaigns.has(c.id));

// Same ambiguity guard as 'Get distinct customers': if more than one client
// (with no campaigns yet) claims the same google_ads_customer_id, there's no
// safe way to know which one newly-discovered campaigns belong to -- skip
// that customer_id entirely rather than picking one arbitrarily. Without
// this, 'Filter new campaigns' would collapse both into a single Map entry
// keyed by customerId and attribute every discovered campaign to whichever
// client happened to be last, silently starving the other.
const clientIdsByCustomerId = new Map();
for (const c of pending) {
  const customerId = String(c.google_ads_customer_id).replace(/[^0-9]/g, '');
  if (!clientIdsByCustomerId.has(customerId)) clientIdsByCustomerId.set(customerId, []);
  clientIdsByCustomerId.get(customerId).push(c.id);
}

const out = [];
for (const c of pending) {
  const customerId = String(c.google_ads_customer_id).replace(/[^0-9]/g, '');
  if (clientIdsByCustomerId.get(customerId).length > 1) continue;
  out.push({
    json: {
      customerId,
      clientId: c.id,
      loginCustomerId: DIRECT_ACCESS_CUSTOMER_IDS.includes(customerId) ? '' : mccCustomerId,
      knownResources: [],
    },
  });
}
return out;

const prepared = $('Prepare suggestion').all().map(i => i.json);
const allRecent = $input.all().map(i => i.json).filter(r => r && r.id);

const ONE_DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();

return prepared.map((p) => {
  if (!p.shouldPost) return { json: p };

  const recentForCampaign = allRecent.filter(r => r.campaign_id === p.campaignRowId);
  // Don't repeat an actionable suggestion the agency hasn't confirmed or
  // dismissed yet -- it's still sitting there, re-posting it is just noise.
  const hasUnresolvedActionable = recentForCampaign.some(r => r.action_status === 'proposed');
  // Also throttle non-actionable/informational nudges (no confirm/dismiss
  // buttons, so they'd otherwise repeat every sync forever) to once a day.
  const hasRecentAny = recentForCampaign.some((r) => {
    const age = now - new Date(r.created_at).getTime();
    return age < ONE_DAY_MS;
  });

  if (hasUnresolvedActionable || hasRecentAny) {
    return { json: { ...p, shouldPost: false } };
  }
  return { json: p };
});
